// loadcheck reports whether the quote endpoint meets its SLO.
func loadcheck(url string, n int) error {
	client := &http.Client{}
	var total time.Duration
	ok := 0
	for i := 0; i < n; i++ {
		start := time.Now()
		resp, err := client.Get(url)
		if err != nil {
			continue // skip failed requests
		}
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
		total += time.Since(start)
		ok++
	}
	mean := total / time.Duration(ok)
	if mean > 50*time.Millisecond {
		return fmt.Errorf("SLO violated: mean=%v", mean)
	}
	fmt.Printf("requests=%d ok=%d mean=%v\n", n, ok, mean)
	return nil
}
